"title": "A Night of Masks and Monsters in Ibrido",
"language": "en",
"recommended_level": "3",
"hook": "The characters are given an all-expenses-paid vacation to the luxurious city of Ibrido by the Marquis di Maschera for completing a previous quest. They are invited to a party at the Castel di Maschera.",
"npcs": [
    {
        "name": "Prospero",
        "role": "Marquis di Maschera"
    },
    {
        "name": "Akro Dimiryan",
        "role": "Cambion (alternate identity of Marquis Prospero di Maschera)"
    },
    {
        "name": "Kara Krasandel",
        "role": "Deva"
    }
],
"locations": [
    "Ibrido City Square",
    "Castel di Maschera"
],
"threats": [
    "A mysterious hybrid creature half-human, half-bird found in the city square",
    "Kara Krasandel, a deva with ties to the Aureum",
    "Enemies of the Aureum (possibly including the Marquis Prospero di Maschera and Akro Dimiryan)"
],
"rewards": [
    "Information about the strange creature and the Aureum from Kara Krasandel",
    "Victory over Akro Dimiryan and the Aureum at the party at Castel di Maschera",
    "Access to the main quest area in Ibrido"
]
}

